import{_ as a,a0 as i,w as s,s as T,I as o,x as n,a1 as e,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150521 Linux FAQs with Answers--How to install Unity Tweak Tool on Ubuntu desktop","title":"Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool","tag":"201506","desc":""},"relativePath":"201506/20150521 Linux FAQs with Answers--How to install Unity Tweak Tool on Ubuntu desktop.md","filePath":"[post].md"}'),p={name:"201506/20150521 Linux FAQs with Answers--How to install Unity Tweak Tool on Ubuntu desktop.md"};function d(k,t,U,w,y,b){const u=i("Link");return s(),T("div",null,[t[15]||(t[15]=o("h1",{id:"linux-有問必答-如何在桌面版-ubuntu-中安裝-unity-tweak-tool",tabindex:"-1"},[n("Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool "),o("a",{class:"header-anchor",href:"#linux-有問必答-如何在桌面版-ubuntu-中安裝-unity-tweak-tool","aria-label":"Permalink to “Linux 有問必答：如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool”"},"​")],-1)),t[16]||(t[16]=o("blockquote",null,[o("p",null,[o("strong",null,"問題"),n(": 我試着給剛安裝的桌面版 Ubuntu 自定製桌面。我想使用 Unity Tweak Tool。我怎樣才能在 Ubuntu 上安裝 Unity Tweak Tool 呢？")])],-1)),o("p",null,[e(u,{href:"https://launchpad.net/unity-tweak-tool"},{default:l(()=>[...t[0]||(t[0]=[n("Unity Tweak Tool",-1)])]),_:1}),t[1]||(t[1]=n(" 是個流行的 Unity 桌面自定製工具。顧名思義，該工具只適用於 Ubuntu 的默認桌面環境(例如，基於 Unity 的 GNOME 桌面)。這個多功能的工具允許你通過非常直觀和簡單易用的圖形用户界面自定義多種 Unity 桌面特性。它的菜單看起來類似於 Ubuntu 的官方系統設置，但它的桌面自定製能力遠遠超過默認的系統設置。通過使用 Unity Tweak Tool，你可以自定製外觀、行為以及很多桌面組件的配置，例如工作區、窗口、圖標、主題、光標、字體、滑動、熱鍵等等。如果你是 Unity 桌面用户，Unity Tweak Tool 一定是個必不可少的應用程序。",-1))]),t[17]||(t[17]=r(`<p><img src="https://farm6.staticflickr.com/5463/17684020389_25dc7f0db2_b.jpg" alt=""></p><p>儘管 Unity Tweak Tool 是桌面版 Ubuntu 的重要工具，但並沒有在桌面版 Ubuntu 中預安裝。為了能自定製 Unity 桌面，下面介紹一下如何在桌面版 Ubuntu 中安裝 Unity Tweak Tool。</p><h3 id="在-ubuntu-13-04-或更高版本中安裝-unity-tweak-tool" tabindex="-1">在 Ubuntu 13.04 或更高版本中安裝 Unity Tweak Tool <a class="header-anchor" href="#在-ubuntu-13-04-或更高版本中安裝-unity-tweak-tool" aria-label="Permalink to “在 Ubuntu 13.04 或更高版本中安裝 Unity Tweak Tool”">​</a></h3><p>從 Ubuntu 13.04 開始， Ubuntu 的基礎庫中就有 Unity Tweak Tool 了。因此它的安裝非常簡單：</p><pre><code>$ sudo apt-get install unity-tweak-tool 
</code></pre><p>啓動 Unity Tweak Tool：</p><pre><code>$ unity-tweak-tool 
</code></pre><p>如果你想使用最新版本的 Unity Tweak Tool，你可以從它的 PPA 中安裝(如下所述)。</p><h3 id="在-ubuntu-12-10-中安裝-unity-tweak-tool" tabindex="-1">在 Ubuntu 12.10 中安裝 Unity Tweak Tool <a class="header-anchor" href="#在-ubuntu-12-10-中安裝-unity-tweak-tool" aria-label="Permalink to “在 Ubuntu 12.10 中安裝 Unity Tweak Tool”">​</a></h3><p>注意，Unity Tweak Tool 要求 Ubuntu 12.10 或更高的版本。如果你想着 Ubuntu 上安裝它，你可以安裝下面方法使用 PPA。當你想測試最新的開發版的時候這個 PPA 庫也非常有用。</p><pre><code>$ sudo add-apt-repository ppa:freyja-dev/unity-tweak-tool-daily
$ sudo apt-get update
$ sudo apt-get install unity-tweak-tool 
</code></pre><hr>`,12)),o("p",null,[t[3]||(t[3]=n("via: ",-1)),e(u,{href:"http://ask.xmodulo.com/install-unity-tweak-tool-ubuntu-desktop.html"},{default:l(()=>[...t[2]||(t[2]=[n("http://ask.xmodulo.com/install-unity-tweak-tool-ubuntu-desktop.html",-1)])]),_:1})]),o("p",null,[t[7]||(t[7]=n("作者：",-1)),e(u,{href:"http://ask.xmodulo.com/author/nanni"},{default:l(()=>[...t[4]||(t[4]=[n("Dan Nanni",-1)])]),_:1}),t[8]||(t[8]=n(" 譯者：",-1)),e(u,{href:"https://github.com/ictlyh"},{default:l(()=>[...t[5]||(t[5]=[n("ictlyh",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),e(u,{href:"https://github.com/wxy"},{default:l(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創翻譯，",-1)),e(u,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const L=a(p,[["render",d]]);export{f as __pageData,L as default};
